const r = $('Find Issues').first().json.report || {};
const stale = Array.isArray(r.stale_findings) ? r.stale_findings : [];
const critical = Array.isArray(r.critical_unresolved) ? r.critical_unresolved : [];
const total = r.total_issues || 0;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function money(n) { return n != null ? Number(n).toLocaleString('es-ES') + 'eur' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }
const sevColor = { low: '#888', medium: '#3b82f6', high: '#e67e22', critical: '#c00' };

const rowsCritical = critical.map(f => `<tr style="background:#fee">
  <td><span style="background:${sevColor[f.severity] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px">${esc(f.severity)}</span>${f.affects_safety ? ' <strong style="color:#c00">SAFETY</strong>' : ''}</td>
  <td>${esc(f.type)}</td>
  <td>${esc(f.project_name)}</td>
  <td>${esc(f.status)}</td>
  <td style="font-size:12px">${esc((f.description || '').substring(0,80))}</td>
  <td style="text-align:right;font-weight:600">${f.days_since_detected}d</td>
</tr>`).join('');

const rowsStale = stale.map(f => `<tr style="background:${f.days_stale > 60 ? '#fee' : '#fff8e0'}">
  <td><span style="background:${sevColor[f.severity] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px">${esc(f.severity)}</span></td>
  <td>${esc(f.type)}</td>
  <td>${esc(f.project_name)}</td>
  <td>${esc(f.status)}</td>
  <td>${dateShort(f.updated_at)}</td>
  <td style="text-align:right">${money(f.cost_min)} - ${money(f.cost_max)}</td>
  <td style="text-align:right;font-weight:600">${f.days_stale}d</td>
</tr>`).join('');

const sections = [];
if (critical.length > 0) {
  sections.push(`<h3 style="margin-top:24px;color:#c00">Critical o afectan seguridad sin resolver (${critical.length})</h3><p style="font-size:13px;color:#555">Findings con severity=critical o affects_safety=true que aun no estan en repaired/dismissed. Prioritarios.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">severidad</th><th align="left">tipo</th><th align="left">proyecto</th><th align="left">status</th><th align="left">descripcion</th><th align="right">dias</th></tr></thead><tbody>${rowsCritical}</tbody></table>`);
}
if (stale.length > 0) {
  sections.push(`<h3 style="margin-top:24px">Findings sin actualizar >30d (${stale.length})</h3><p style="font-size:13px;color:#555">Patologias detectadas hace mas de 30 dias que siguen en detected/confirmed/scheduled/in_repair (no terminales). Revisar estado real y actualizar.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">severidad</th><th align="left">tipo</th><th align="left">proyecto</th><th align="left">status</th><th align="left">ultimo update</th><th align="right">coste est</th><th align="right">dias stale</th></tr></thead><tbody>${rowsStale}</tbody></table>`);
}

const html = `<div style="font-family:system-ui,sans-serif;color:#222;max-width:820px">
<h2>Patologias - revision diaria (${total} pendientes)</h2>
${sections.join('\n')}
<p style="font-size:12px;color:#888;margin-top:24px">cron_pathology_review - generado ${new Date().toISOString()}</p>
</div>`;

const subject = `[Patologias] ${total} pendientes (${critical.length} criticas/safety + ${stale.length} sin actualizar >30d)`;

return [{ json: { html, subject, total } }];
